// Cloudflare on the business's own API token, or a sign-in through our OAuth client: every operation of Cloudflare's
// public API a normal account can call (zones and DNS, registrar, Pages, Workers and their storage, SSL, cache, WAF and
// rules, Zero Trust, email routing, analytics, Radar…). actions.json is generated by `bun scripts/openapi-actions.ts
// cloudflare`; COVERAGE.md says what's left out. Alerts arrive by webhook (triggers.ts), the rest is polled (polls/cloudflare.ts).
import { z } from "zod";
import { AppsError } from "../../types";
import type { OwnAction, OwnApp } from "../index";
import { postToken } from "../oauth";
import { type Api, call, type Send, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const BASE = "https://api.cloudflare.com/client/v4";
const TOKENS = "dash.cloudflare.com/profile/api-tokens";
type Errors = { errors?: { code?: number; message?: string; error_chain?: { code?: number }[] }[] };
const codes = (body: unknown) => ((body as Errors)?.errors ?? []).flatMap((e) => [e.code, ...(e.error_chain ?? []).map((c) => c.code)]);

const api: Api = {
  name: "Cloudflare",
  base: BASE,
  tokenHelp: TOKENS,
  // 1000: invalid token; 6111/6103: not a token at all. 10000 / 9109 is a token that lacks a permission, not a dead one
  deadToken: (status, body) => status === 401 || codes(body).some((c) => c === 1000 || c === 6111 || c === 6103),
};

// Cloudflare explains a failure as {"errors": [{"code", "message"}]}, which call() hands back raw: say it plainly
function explain(error: unknown): never {
  if (!(error instanceof AppsError) || error.expired) throw error;
  const m = error.message.match(/^Cloudflare: (\{[\s\S]*\}) \((\d+)\)$/);
  const body = m ? (JSON.parse(m[1]!) as Errors) : null;
  if (!body?.errors?.length) throw error;
  const said = body.errors.map((e) => `${e.message ?? "error"}${e.code ? ` (code ${e.code})` : ""}`).join("; ");
  const permission = codes(body).some((c) => c === 10000 || c === 9109) ? `. The token may lack the permission for this: edit it at ${TOKENS}` : "";
  throw new AppsError(`Cloudflare: ${said}${permission} (${m![2]})`);
}

// Calls whose body is plain text or NDJSON (SQL, Zaraz workflow, vectors), which the generator can't send
async function text(method: string, path: string, type: string, input: Record<string, unknown>, key: string, body: string) {
  const url = BASE + path.replace(/\{(\w+)\}/g, (_, k) => encodeURIComponent(String(input[k] ?? "")));
  const res = await fetch(url, { method, headers: { Authorization: `Bearer ${key}`, "Content-Type": type }, body });
  const out = await res.text();
  const json = (() => {
    try {
      return JSON.parse(out);
    } catch {
      return out;
    }
  })();
  if (api.deadToken!(res.status, json)) throw new AppsError(`Cloudflare rejected the token; make a new one (${TOKENS}) and reconnect`, true);
  if (!res.ok) explain(new AppsError(`Cloudflare: ${out} (${res.status})`));
  return json;
}
const ACCOUNT = z.string().describe("The Cloudflare account's id (32 hex characters): cloudflare.list_accounts lists them");
const ZONE = z.string().describe("The zone's (domain's) id: cloudflare.list_zones lists them");

const hand: Record<string, OwnAction> = {
  query_graphql_analytics: {
    description:
      "Ask Cloudflare's GraphQL Analytics API: traffic, requests, bandwidth, threats, cache, Workers and Pages usage for zones and accounts, over any time range. Read-only. Example query: { viewer { zones(filter: {zoneTag: \"<zone id>\"}) { httpRequests1dGroups(limit: 7, filter: {date_gt: \"2026-01-01\"}) { dimensions { date } sum { requests bytes threats } } } } }",
    readOnly: true,
    input: z.object({
      query: z.string().describe("The GraphQL query (Cloudflare's analytics schema: viewer → zones/accounts → datasets like httpRequests1dGroups, httpRequestsAdaptiveGroups, workersInvocationsAdaptive)"),
      variables: z.record(z.string(), z.unknown()).optional().describe("Values for $variables in the query"),
    }),
    run: (input, key) => call(api, key, { method: "POST", path: "/graphql", query: [], headers: [], body: { kind: "fields", fields: [["query", "query"], ["variables", "variables"]] } }, input),
  },
  query_analytics_sql: {
    description: "Run a SQL query on a Workers Analytics Engine dataset (the data a Worker writes with writeDataPoint). Read-only. Example: SELECT blob1, count() FROM my_dataset WHERE timestamp > NOW() - INTERVAL '1' DAY GROUP BY blob1",
    readOnly: true,
    input: z.object({ account_id: ACCOUNT, sql: z.string().describe("The SQL query") }),
    run: (i, key) => text("POST", "/accounts/{account_id}/analytics_engine/sql", "text/plain", i, key, i.sql),
  },
  query_account_logs_sql: {
    description: "Run a SQL query on an account's Log Explorer datasets (Log Explorer must be on). Read-only.",
    readOnly: true,
    input: z.object({ account_id: ACCOUNT, sql: z.string().describe("The SQL query, like SELECT * FROM http_requests WHERE ... LIMIT 100") }),
    run: (i, key) => text("POST", "/accounts/{account_id}/logs/explorer/query/sql", "text/plain", i, key, i.sql),
  },
  query_zone_logs_sql: {
    description: "Run a SQL query on a zone's Log Explorer datasets (Log Explorer must be on). Read-only.",
    readOnly: true,
    input: z.object({ zone_id: ZONE, sql: z.string().describe("The SQL query, like SELECT * FROM http_requests WHERE ... LIMIT 100") }),
    run: (i, key) => text("POST", "/zones/{zone_id}/logs/explorer/query/sql", "text/plain", i, key, i.sql),
  },
  update_zaraz_workflow: {
    description: "Choose how Zaraz (third-party tools on the site) is set up for a zone: realtime, or preview mode.",
    input: z.object({ zone_id: ZONE, workflow: z.enum(["realtime", "preview"]).describe("realtime: changes go live at once; preview: test them first") }),
    run: (i, key) => text("PUT", "/zones/{zone_id}/settings/zaraz/workflow", "application/json", i, key, JSON.stringify(i.workflow)),
  },
  ...Object.fromEntries(
    (["insert", "upsert"] as const).map((verb): [string, OwnAction] => [
      `${verb}_vectors`,
      {
        description: `${verb === "insert" ? "Add" : "Add or replace"} vectors in a Vectorize index.`,
        input: z.object({
          account_id: ACCOUNT,
          index_name: z.string().describe("The Vectorize index"),
          vectors: z.array(z.object({ id: z.string(), values: z.array(z.number()), metadata: z.record(z.string(), z.unknown()).optional(), namespace: z.string().optional() }).loose()).describe("The vectors: each an id, its values (as many as the index's dimensions), and optional metadata"),
        }),
        run: (i, key) => text("POST", `/accounts/{account_id}/vectorize/v2/indexes/{index_name}/${verb}`, "application/x-ndjson", i, key, i.vectors.map((v: unknown) => JSON.stringify(v)).join("\n")),
      },
    ]),
  ),
};

const actions: OwnApp["actions"] = { ...(await specActions(new URL("./actions.json", import.meta.url), api)), ...hand };
for (const a of Object.values(actions)) {
  const run = a.run;
  a.run = (input, key, connection) => run(input, key, connection).catch(explain);
}

const get = (path: string): Send => ({ method: "GET", path, query: [], headers: [] });

// Our OAuth client on dash.cloudflare.com. Its scopes are picked when it's registered (Cloudflare lists them only to a
// signed-in account), so the server is told them: CLOUDFLARE_OAUTH_SCOPES, space separated. offline_access for a refresh token.
const client = () => ({ Authorization: `Basic ${Buffer.from(`${process.env.CLOUDFLARE_CLIENT_ID}:${process.env.CLOUDFLARE_CLIENT_SECRET}`).toString("base64")}` });
const TOKEN = "https://dash.cloudflare.com/oauth2/token";

export const cloudflare: OwnApp = {
  app: "cloudflare",
  name: "Cloudflare",
  logo: "/logos/cloudflare.svg",
  keyField: {
    label: "API token",
    help: `${TOKENS} → Create Token. Use a template (like "Edit zone DNS") or a custom token with what Emplio should do: Zone and DNS, Workers and Pages, SSL, Cache, Firewall, Email Routing, and Notifications (Edit) for automations; pick the accounts and zones it covers.`,
    placeholder: "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
  },
  // A user token verifies at /user/tokens/verify; an account-owned token (and an OAuth login) doesn't, but lists its accounts
  async check(key) {
    const user = (await call(api, key, get("/user/tokens/verify"), {}).catch(() => null)) as { result?: { status?: string } } | null;
    if (user?.result?.status && user.result.status !== "active") throw new AppsError(`Cloudflare says this token is ${user.result.status}; make a new one at ${TOKENS}`);
    const accounts = (await call(api, key, { ...get("/accounts"), query: ["per_page"] }, { per_page: 50 }).catch((e) => {
      if (!user) throw e instanceof AppsError ? new AppsError(`Cloudflare didn't accept the token: ${e.message}`) : e;
      return null;
    })) as { result?: { name: string }[] } | null;
    const names = accounts?.result?.map((a) => a.name) ?? [];
    return names.length === 1 ? names[0] : names.length ? `${names[0]} and ${names.length - 1} more` : undefined;
  },
  oauth: {
    ready: () => Boolean(process.env.CLOUDFLARE_CLIENT_ID && process.env.CLOUDFLARE_CLIENT_SECRET && process.env.CLOUDFLARE_OAUTH_SCOPES),
    // prompt=consent: always a screen to approve on, so a sign-in link someone was sent can't finish by itself
    authorizeUrl: (redirect, state) =>
      `https://dash.cloudflare.com/oauth2/auth?${new URLSearchParams({
        response_type: "code",
        client_id: process.env.CLOUDFLARE_CLIENT_ID!,
        redirect_uri: redirect,
        scope: [...new Set([...process.env.CLOUDFLARE_OAUTH_SCOPES!.split(/[\s,]+/).filter(Boolean), "offline_access"])].join(" "),
        state,
        prompt: "consent",
      })}`,
    exchange: (code, redirect) => postToken("Cloudflare", TOKEN, { grant_type: "authorization_code", code, redirect_uri: redirect }, client()),
    refresh: (refreshToken) => postToken("Cloudflare", TOKEN, { grant_type: "refresh_token", refresh_token: refreshToken }, client()),
    async revoke(token) {
      await fetch("https://dash.cloudflare.com/oauth2/revoke", {
        method: "POST",
        headers: { ...client(), "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({ token }).toString(),
        signal: AbortSignal.timeout(30_000),
      });
    },
  },
  push: {
    events,
    triggers,
    start: (key, connection, event, config) => watch(api, key, connection, event, config),
    stop: (key, id) => unwatch(api, key, id),
    receive,
    wanted,
  },
  actions,
};
